from pathlib import Path
from html import escape as E
import re, json, hashlib, zipfile

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'output/PM-001_20261029'
OUT.mkdir(exist_ok=True)
NAME='20261029__PLSQL__TETOOLS_ADMIN_OBJECTS__ontwerp_profielmanifest_001_STE_001.html'
sections=[]
def p(s): return '<p>'+s+'</p>'
def ul(*items): return '<ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
def table(headers, rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def code(s): return '<pre><code>'+E(s)+'</code></pre>'
def ref(*ids): return '<sup>'+ ' '.join('<a href="#'+i+'">['+i+']</a>' for i in ids)+'</sup>'
def tag(status): return '<span class="badge '+status.lower()+'">'+status+'</span>'
def add(i,title,status,area,body,source):
    sections.append((i,title,status,area,'<details class="chapter" id="'+i+'" data-status="'+status+'" data-area="'+area+'" open><summary><span class="point">'+i+'</span><span>'+title+'</span>'+tag(status)+'</summary><div class="body"><p class="evidence">Basis: '+ref(*source)+'</p>'+body+'<p class="back"><a href="#contents">Back to contents</a></p></div></details>'))

add('PM-001-01','Purpose, scope and reading rules','Agreed','Architecture',
p('This document records the profile manifest PM-001 and the preceding architecture decisions for <code>TETOOLS.ADMIN_OBJECTS</code>. The platform scope is Oracle Database 19c Enterprise. It is a design reference for this module and for later TETOOLS modules. It does not define an installed implementation.')+
p('The fingerprint supports installation checks and the detection of configuration changes. It reduces repeated work when an object already exists. It does not identify a release by itself. It does not certify the quality of a delivery or replace the developer or administrator.')+
table(['Label','Meaning'],[
['Agreed','An explicit user decision, or an agreed design direction. The cited source determines the scope.'],
['Proposal','A concrete design from the earlier conversation, or a clearly marked implementation recommendation. It is not an approved database contract.'],
['Open','A policy or technical choice still needs a decision or a test.'],
['Mixed','The chapter contains items with different statuses. Each item identifies its status.'],
['Technical note','An Oracle 19c fact or an engineering implication, with a source. It does not create a new project agreement.']])+
p('The document uses clear English inspired by ASD-STE100. No formal compliance or measured percentage is claimed. Code and record examples use Courier New, 11 pt. Navy identifies headings; turquoise identifies navigation and accents. Status labels contain text as well as colour. No code replacement, addition or deletion colours are used because no existing code is changed.'),['S01','S02','S03','S10'])

add('PM-001-02','Architecture and responsibility boundaries','Agreed','Architecture',
table(['Layer','Responsibility','Boundary'],[
['Profile manifest','Define metadata sources, component scope, properties, normalisation and order. Store the versioned definitions.','It does not decide installation permission.'],
['Extractor and normaliser','Read current Oracle metadata and build typed object records using one selected profile.','A failed extraction is not absence.'],
['Object manifest','Hold the selected, normalised values of one object. Generate it ad hoc.','It is not a permanent full history by default.'],
['Canonical serializer','Encode the selected records as deterministic bytes.','Display text, indentation and JSON presentation do not define the bytes.'],
['Fingerprint calculation','Hash the complete canonical input under the stated algorithm.','It has no numeric severity or installation authority.'],
['Component inventory','Describe the types and identities of components included in that calculation.','Diagnostic only; never an input to the hash.'],
['Ledger and installation history','Link observations and successful installations to objects, versions and calculation context.','A historical hash is not a complete old object definition.'],
['Preflight and administrator','Apply technical gates; report findings; make operational decisions within installation rules.','No release-quality guarantee and no new object relationship manager.']])+
'''<figure><svg viewBox="0 0 920 320" role="img" aria-labelledby="flow-title flow-desc"><title id="flow-title">Manifest and fingerprint data flow</title><desc id="flow-desc">A versioned profile and Oracle metadata feed one extraction. The object manifest feeds canonical bytes and the fingerprint. A separate branch produces the diagnostic inventory.</desc><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#476778"/></marker></defs><g fill="#edf5f7" stroke="#688b9a"><rect x="15" y="20" width="260" height="60" rx="8"/><rect x="15" y="115" width="260" height="60" rx="8"/><rect x="335" y="65" width="245" height="70" rx="8"/><rect x="650" y="25" width="250" height="65" rx="8"/><rect x="650" y="125" width="250" height="65" rx="8"/><rect x="335" y="235" width="565" height="60" rx="8"/></g><g stroke="#476778" stroke-width="2" fill="none" marker-end="url(#arrow)"><path d="M275 50L335 90"/><path d="M275 145L335 110"/><path d="M580 90L650 60"/><path d="M775 90L775 125"/><path d="M455 135L455 235"/></g><g text-anchor="middle" fill="#173647" font-family="Arial,sans-serif" font-size="17"><text x="145" y="56">Versioned profile</text><text x="145" y="151">Oracle dictionary metadata</text><text x="458" y="94">One extraction</text><text x="458" y="117">Typed object manifest</text><text x="775" y="63">Canonical bytes</text><text x="775" y="163">Fingerprint</text><text x="617" y="270">Diagnostic inventory — no path into the hash</text></g></svg><figcaption>Figure 1. The profile controls interpretation. The inventory describes one calculation.</figcaption></figure>'''+
p('The PoC will use SQL and PL/SQL inside Oracle 19c. It may start with a manually defined profile and test metadata. Automation, approval workflows, scheduler integration and a production installation engine are later work. The current assignment delivers documentation only.'),['S03','S04','S05','S10'])

add('PM-001-03','Object scope and optional or repeated components','Mixed','Architecture',
p('<strong>Agreed:</strong> the design must support different object categories, optional components and repeated components. Each independently managed object has its own fingerprint. The profile defines which internal components belong to its scope. Do not create an independent relationship or dependency registry.')+
table(['Object family reported by the user','Design treatment','Implementation status'],[
['Tables; table partitions; LOBs; LOB partitions','A table profile can include selected internal structure. Presence and applicable details must be explicit.','Table PoC only; exact extended scope open.'],
['Indexes; index partitions','An independently managed index has its own profile and fingerprint. Supporting indexes require an explicit profile boundary.','Not implemented.'],
['Packages: specification and body; one specification used for types without a body','The profile must represent the supported object shape; do not assume that every specification has a body.','Specification/body grouping open.'],
['Functions; procedures; triggers; types; views; materialized views; sequences','Separate managed object categories. Do not infer all related objects into a table fingerprint.','Future profile definitions.'],
['Database links; jobs; queues','Reported objects in the schema; identity and metadata extraction need category-specific design.','Future profile definitions.']])+
p('<strong>Technical interpretation:</strong> present dictionary metadata describes current constraints and supporting indexes. It is insufficient evidence of the original inline versus later <code>ALTER TABLE</code> syntax. Define membership by explicit current-metadata rules; do not reconstruct DDL provenance from object names.'+ref('O-CON'))+
p('<strong>Open:</strong> constraint identity, generated index inclusion, duplicate semantic constraints, partitions, subpartitions and LOB details require exact rules. An unsupported object shape must be visible as unsupported; it must not receive a misleading complete-coverage label. This last rule is a proposed implementation safeguard.'),['S06','S07','S10'])

add('PM-001-04','PM-001 logical structure and profile identity','Proposal','Profile',
p('PM-001 proposes five logical groups: <code>PROFILE</code>, <code>COMPONENT</code>, <code>PROPERTY</code>, <code>NORMALIZATION</code> and <code>SERIALIZATION</code>. These groups do not require five physical tables. The following fields reproduce the PM-001 proposal; physical lengths, constraints and storage are not approved.')+
table(['PROFILE field','Logical type','Example','Required in proposal'],[
['PROFILE_CODE','VARCHAR2','TABLE_CORE','Yes'],['PROFILE_VERSION','NUMBER','1','Yes'],['PROFILE_NAME','VARCHAR2','Table core structure','Yes'],['OBJECT_TYPE','VARCHAR2','TABLE','Yes'],['SUBJECT','VARCHAR2','Table metadata','Yes'],['DESCRIPTION','VARCHAR2 / CLOB','Functional explanation','Yes'],['CANONICAL_VERSION','NUMBER','1','Yes'],['HASH_ALGORITHM','VARCHAR2','SHA256','Yes'],['PROFILE_STATUS','VARCHAR2','DRAFT','Yes']])+
p('The logical key is <code>(PROFILE_CODE, PROFILE_VERSION)</code>. Once a profile version supports accepted fingerprints, its interpretation rules remain immutable. A changed interpretation requires a new profile version. Administrative name, subject and description do not enter the hash. Profile code, profile version and canonical format version enter its header.')+
p('<strong>Open terminology:</strong> earlier examples use <code>PROFILE_ID</code> and <code>CANONICAL_FORMAT_VERSION</code>. PM-001 uses <code>PROFILE_CODE</code> and <code>CANONICAL_VERSION</code>. Use the logical profile key for portable comparison; a physical surrogate ID must not silently change the hash between environments. This is a proposed clarification, not a settled schema change.'),['S10','S11'])

add('PM-001-05','COMPONENT definition and cardinality','Proposal','Profile',
table(['Field','Meaning'],[
['COMPONENT_ID','Stable numeric component-category identifier.'],['COMPONENT_CODE','Category, for example COLUMN, CONSTRAINT or PARTITION.'],['PARENT_COMPONENT_ID','Optional parent category for nested components.'],['SOURCE_CODE','An allowed metadata-extractor identifier.'],['MIN_OCCURS / MAX_OCCURS','Required minimum and allowed maximum; an explicit unlimited convention is still needed.'],['IDENTITY_RULE','How an individual component is identified.'],['ORDER_RULE','How repeated components receive a deterministic order.'],['ABSENCE_RULE','How relevant absence is represented.'],['DESCRIPTION','Documentation.']])+
table(['Proposed ID','Category','Occurrences','Identity','Order'],[
['010','TABLE','1','Main object','Fixed'],['020','COLUMN','1..N','Column name','COLUMN_ID'],['030','CONSTRAINT','0..N','Canonical constraint identity','Semantic key'],['040','PARTITIONING','0..1','Main object','Fixed'],['050','PARTITION','0..N','Partition identity','Partition position'],['060','LOB','0..N','LOB column','Stable column identity']])+
p('A component is a logical part of the inspected main object. It need not be an independent Oracle schema object. Relevant optional absence belongs in the object manifest. The inventory lists present components only. Repeated elements require stable identities, explicit membership and a complete order.')+
p('<strong>Open:</strong> define identity scope for nested elements, including parent identity. Decide how zero occurrences, duplicate identities, duplicate semantic keys and null positions are validated. Numeric IDs above are category IDs, not Oracle dictionary object numbers.'),['S10'])

add('PM-001-06','PROPERTY definition and first table mapping','Proposal','Profile',
table(['Field','Meaning'],[
['PROPERTY_ID','Stable property identifier within its component category.'],['PROPERTY_CODE','Technical name, such as DATA_TYPE.'],['SOURCE_ATTRIBUTE','Dictionary attribute or a derived property.'],['VALUE_TYPE','Logical type, such as STRING, INTEGER or BOOLEAN.'],['NORMALIZER_CODE','A selected known rule.'],['NULL_POLICY','How a null value is interpreted.'],['IN_FINGERPRINT','Whether the property enters canonical hash input.'],['DESCRIPTION','Meaning and explanation.']])+
table(['Component','Property','Oracle 19c source','Hash in PM-001'],[
['TABLE','TABLESPACE_NAME','ALL_TABLES','Yes'],['COLUMN','COLUMN_NAME','ALL_TAB_COLS','Yes'],['COLUMN','COLUMN_ID','ALL_TAB_COLS','Yes'],['COLUMN','DATA_TYPE','ALL_TAB_COLS','Yes'],['COLUMN','DATA_PRECISION','ALL_TAB_COLS','Yes'],['COLUMN','DATA_SCALE','ALL_TAB_COLS','Yes'],['COLUMN','CHAR_LENGTH','ALL_TAB_COLS','When applicable'],['COLUMN','CHAR_USED','ALL_TAB_COLS','When applicable'],['COLUMN','NULLABLE','ALL_TAB_COLS','Yes']])+
p('These dictionary mappings are checked against the Oracle 19c documentation.'+ref('O-COLS','O-TAB'))+
p('<strong>Open:</strong> the earlier PoC list included <code>DATA_LENGTH</code>. PM-001 omits it. The earlier discussion also proposed keeping it as diagnostic information when character length semantics are used. Decide inclusion by datatype before freezing TABLE_CORE v1. A data type name alone cannot represent every type parameter.')+
p('The profile must specify an applicability predicate, null handling and normalisation for each selected property. A null dictionary value must not cause silent omission. Precision for <code>NUMBER</code> and <code>FLOAT</code> has different documented meaning. The PoC must either support those meanings explicitly or restrict its datatype scope.'+ref('O-COLS')),
['S10','S11'])

add('PM-001-07','Normalisation rules and missing information','Proposal','Canonical format',
table(['Rule code','Required behaviour in PM-001'],[
['IDENTIFIER_EXACT','Preserve dictionary spelling and case. Do not uppercase quoted identifiers.'],['INTEGER_DECIMAL','Use a deterministic decimal integer representation, independent of session NLS settings.'],['ENUM_UPPER','Convert to an explicitly allowed uppercase code; reject unknown codes.'],['NULL_EXPLICIT','Encode a permitted null as a distinct value state.'],['NOT_APPLICABLE','Represent a property that does not apply under its profile rule.'],['ORDER_POSITION','Preserve functional position where the profile makes it significant.'],['ORDER_IDENTITY','Sort on a stable component identity.'],['PRESENCE_FLAG','Represent relevant presence or absence explicitly.']])+
table(['State','Meaning','Outcome'],[
['Value present','Metadata was read and validated.','Normalise the typed value.'],['NULL','A permitted dictionary null.','Use an explicit null code.'],['Not applicable','The profile establishes that the property does not apply.','Use the specified N/A code or representation.'],['Unknown / unreadable','Extraction, access or validation failed.','Fail the calculation; do not create a valid partial fingerprint.'],['Absent optional component','A complete applicable extraction established absence.','Represent relevant absence in the object manifest; no absent item in inventory.']])+
p('The PoC proposal uses known extractor and normaliser codes. It does not store arbitrary executable SQL or PL/SQL in the profile. Presentation whitespace must not affect the hash, but meaningful whitespace inside selected expression values must not be discarded without a specific rule.')+
p('<strong>Open:</strong> exact allowed enums, numeric syntax, binary sorting, Unicode handling and Oracle empty-string behaviour must be fixed in the byte-format specification. The earlier illustrative empty-string token is not proof that an Oracle VARCHAR2 value can distinguish an empty string from null.'),['S10','S11'])

add('PM-001-08','Object manifest and deterministic ordering','Proposal','Canonical format',
p('The object manifest consists of typed normalised records. The PM-001 record model uses <code>COMPONENT_ID</code>, <code>COMPONENT_IDENTITY</code>, <code>COMPONENT_POSITION</code>, <code>PROPERTY_ID</code>, <code>VALUE_TYPE</code> and <code>VALUE</code>. An explicit value-state representation must distinguish null and not applicable.')+
code('PROFILE_CODE      TABLE_CORE\nPROFILE_VERSION   1\nCANONICAL_VERSION 1\n\nCOMPONENT 020 / LOG_ID / POSITION 1\n  DATA_TYPE       STRING   NUMBER\n  DATA_PRECISION  INTEGER  19\n  DATA_SCALE      INTEGER  0\n  NULLABLE        ENUM     N\n\nCOMPONENT 020 / LOG_MESSAGE / POSITION 2\n  DATA_TYPE       STRING   VARCHAR2\n  CHAR_LENGTH     INTEGER  400\n  CHAR_USED       ENUM     C\n  NULLABLE        ENUM     Y\n\nCOMPONENT 010 / TABLE\n  TABLESPACE_NAME STRING   TETOOLS_DATA')+
p('This is a readable example, not executable SQL and not exact hash input. Names and values are illustrative. No production object was inspected for this example.')+
table(['Order','Rule'],[
['Component categories','Stable component-category ID.'],['Repeated columns','Functional COLUMN_ID order when the profile selects column position. A defined identity tie-breaker is still required.'],['Constraints','A defined semantic key, not query return order. Generated names require a policy.'],['Columns inside composite keys','Preserve the relevant key-column position.'],['Properties','Stable property ID within the selected category.']])+
p('Earlier <code>SECTION_ID</code>, <code>ELEMENT_KEY</code> and <code>ELEMENT_POSITION</code> illustrate a preceding model. PM-001 refines it into components. Do not combine both numeric layouts without a mapping and a new format decision. The normalised records can generate a readable manifest, canonical bytes and the inventory from one extraction.'),['S10','S11'])

add('PM-001-09','Serialization and fingerprint identity','Mixed','Canonical format',
p('<strong>PM-001 proposal:</strong> serialize each field with unambiguous type and byte-length encoding. Encode text as UTF-8. Use different codes for null and not applicable. Encode numbers without NLS-dependent formatting. Fully order records and encode repeated membership so that adding or removing a component changes the canonical input.')+
code('Comparison context =\n  PROFILE_CODE + PROFILE_VERSION + CANONICAL_VERSION\n  + HASH_ALGORITHM + FINGERPRINT\n\nCanonical input = profile header + ordered typed records\nFingerprint    = hash(complete canonical input)')+
p('Administrative descriptions, timestamps, inventory display and severity do not enter canonical input. The inventory is not hashed. Owner and object name were proposed to remain outside the configuration hash so that equivalent selected configurations in different environments can compare. Their registry identity remains separate. This exclusion is still a proposal.')+
p('<strong>Open:</strong> the exact bytes are not yet approved. Define type tags, length width, byte order, record framing, header fields, null/N/A tokens, integer rules, sorting and overflow handling before storing accepted production hashes. A pipe-delimited or readable JSON example is not the canonical protocol. No fabricated example digest is presented as a PM-001 result.')+
p('<strong>Technical note:</strong> <code>STANDARD_HASH</code> in Oracle 19c supports SHA256 and returns RAW. Its input cannot be LONG or a LOB; the default algorithm is SHA1, so the algorithm must be explicit. <code>DBMS_CRYPTO</code> supports LOB hashing and SHA-256, with package-access considerations. These are alternative implementation paths, not a final choice.'+ref('O-HASH','O-CRYPTO'))+
p('For the PoC, PM-001 proposes a bounded complete input and a hard failure on overflow. Production must hash the complete byte representation without truncation. A UTF-8 byte BLOB is a candidate for a large-input path; prove conversion, permissions and RAW output formatting in Oracle before adoption. Independent chunk hashes must not silently replace the agreed whole-input hash.'),['S10','S11'])

add('PM-001-10','Minimal component inventory','Agreed','Inventory',
p('Store only the component type and identity of components present in the calculation scope. The user explicitly accepted the minimal level. Earlier examples with datatype, precision and length are superseded. Do not include absence lines such as <code>PARTITIONED=NO</code>.')+
code('OBJECT: TETOOLS.ADMIN_LOGGER_LOG\nPROFILE: TABLE_CORE / 1\n\nTABLE       ADMIN_LOGGER_LOG\nCOLUMN      LOG_ID\nCOLUMN      LOG_MESSAGE\nCONSTRAINT  PK_ADMIN_LOGGER_LOG')+
p('This is an illustrative display. The selected profile decides whether the shown constraint belongs in the calculation. An index may appear only when that profile includes it. Object/profile/calculation linkage is context for the inventory; it does not expand each component entry with attributes.')+
p('Build the inventory from the same metadata extraction as the object manifest and fingerprint. Store it after a successful installation and calculation. After a successful recalculation, store a separate observed inventory when the fingerprint differs from the accepted reference. Keep both until a corrective action is completed.')+
p('The inventory can explain added or removed identities. It cannot reconstruct an old precision or expression when the component identity stays the same. A changed fingerprint with an unchanged inventory is valid and expected. The developer retains detailed change information in source version control.'),['S07','S08','S09','S10'])

add('PM-001-11','Fingerprint production, catalog and scheduled recalculation','Mixed','Fingerprint',
p('<strong>Agreed:</strong> DEV/TST contain the new objects before promotion. Calculate the offered fingerprints there with the relevant profile versions and deliver them with the installation. ACC/PRD need not parse the offered creation DDL to derive the expected value. After creation or replacement, calculate the target object fingerprint and compare it with the offered claim.')+
p('<strong>Agreed direction:</strong> <code>catalog_admin_objects</code> inventories objects. Separate scheduled processing calculates fingerprints for ledger objects. The ledger records calculation time and success/status context. <code>LAST_FINGERPRINT_TIME</code> was suggested as a field; it is not claimed to exist already.')+
table(['Process','Result','Boundary'],[
['Catalog discovery','Object presence and inventory findings.','Do not invent accepted lifecycle metadata.'],['Scheduled recalculation','Current metadata, correct profile, fingerprint, calculation result and diagnostic inventory.','Do not silently replace an accepted reference on drift.'],['Preflight refresh','Recalculate when the stored fingerprint is unreliable.','Then use the standard decision rules.'],['Post-install verification','Compare actual target fingerprint with offered DEV/TST fingerprint.','Successful DDL alone does not establish successful fingerprint verification.']])+
p('<strong>Proposal:</strong> separate metadata acquisition, pure normalisation and storage coordination. One in-memory record set feeds the outputs. Cache immutable profiles within one run and collect dictionary data per object/category rather than once per property. Measure calls, elapsed time and memory before claiming an improvement.'),['S02','S03','S07','S08'])

add('PM-001-12','Freshness and confidence gate','Mixed','Preflight',
p('<strong>Agreed:</strong> check fingerprint reliability before the installation decision. If it is unreliable, recalculate it. A weekly calculation with a validity window of one week was a user example, not an approved global retention or validity constant.')+
table(['Check','Meaning','Status'],[
['Successful calculation','No extraction, validation, encoding or hashing failure.','Required design direction.'],['Matching profile context','Profile identity, version, canonical format and algorithm are comparable.','Required design direction.'],['Age within configured validity','A stored observation is fresh enough for the intended use.','Exact limit open.'],['Oracle object status','INVALID can indicate a change in the object or its dependencies and can trigger diagnosis/recalculation.','Supporting indication.'],['LAST_DDL_TIME','A DDL-related timestamp; use it as a signal, not complete proof of unchanged composite metadata.','Supporting indication.'],['No other change indication','Use the module’s remaining installation gates.','Exact rules open.']])+
p('Oracle <code>ALL_OBJECTS.STATUS</code> has VALID, INVALID and N/A values. This is separate from calculation success and the module lifecycle status. Do not confuse it with <code>ALL_TABLES.STATUS</code>.'+ref('O-OBJ','O-TAB'))+
p('<strong>Technical interpretation:</strong> equal hashes mean equal selected canonical inputs only within the same context, subject to collision risk and observation age. Different hashes alone do not prove different physical objects if the profile or format changed. No hash value provides a complete change history.'),['S03','S07','S08'])

add('PM-001-13','Delivery manifest: pakbon','Mixed','Installation',
p('<strong>Agreed:</strong> supply a pakbon before executing installation DDL. It lists the main objects to install or replace and their offered fingerprints. A table entry can cover the internal components defined by its profile. Independently managed indexes and triggers are separate main entries.')+
table(['Proposed item field','Purpose'],[
['Installation / release ID','Identify the offered delivery.'],['Owner, main object name and object type','Select the target object without ambiguity.'],['Offered object version','Apply the object-version policy.'],['Profile code and profile version','Identify interpretation rules.'],['Canonical format version','Identify byte-protocol compatibility.'],['Hash algorithm and fingerprint','Represent the offered configuration claim.']])+
p('The pakbon describes what is offered. Installation scripts and the existing process determine execution sequence. The user rejects building a separate relationship manager. Removal of <code>INSTALLATION_ORDER</code> from the pakbon was the explicit follow-up proposal; the field was not retained as a settled requirement.')+
p('<strong>Open:</strong> the physical pakbon format, identifier lengths, uniqueness rules, exception references and delivery-signoff rules are not final. There is no agreed dependency graph, topological sort or composite installation fingerprint. These were earlier suggestions, not the final scope.'),['S08','S09'])

add('PM-001-14','Preflight and execution are separate phases','Agreed','Preflight',
'''<div class="process" role="img" aria-label="Delivery manifest to preflight, findings and decision, execution, verification, then successful registration"><div>Pakbon<br><small>Objects, versions, hashes</small></div><b>→</b><div>Preflight<br><small>Technical gates</small></div><b>→</b><div>Findings / decision<br><small>Release, defer or reject</small></div><b>→</b><div>Execute<br><small>Existing scripts</small></div><b>→</b><div>Verify and register<br><small>Actual target hash</small></div></div>'''+
p('Preflight checks the offered delivery, object versions, historical fingerprints and confidence in the existing fingerprints. It reports blocking and non-blocking findings before installation DDL. A blocking outcome prevents release to execution. Reporting a drift finding does not automatically create a new compulsory manual approval for every installation.')+
p('Execution follows the applicable release decision and installation rules. After creation or modification, calculate and compare the actual target fingerprint. The administrator remains responsible for the operational decision. A new configuration fingerprint supports the comparison but does not prove that the delivery is good.')+
p('Oracle issues implicit commits before syntactically valid DDL and after successful DDL. Preflight reduces avoidable partial installations; it does not make all installation DDL one rollbackable transaction.'+ref('O-DDL'))+
p('<strong>Open:</strong> how to handle object changes between preflight and execution, failed post-install comparison, partial success and retry requires a concrete execution protocol. A recheck before execution is a proposal, not an existing guarantee.'),['S08','S09'])

add('PM-001-15','Installation decision matrix and rule precedence','Mixed','Installation',
p('Apply version and compatibility gates before treating a configuration as a new candidate. Resolve confidence in the existing fingerprint before comparison. The matrix preserves the user’s corrections. “Candidate” means continue the remaining checks, not unconditional permission.')+
table(['ID','Condition','Action','Evidence status'],[
['I-01','Object does not exist.','Install only after applicable preflight gates; calculate actual fingerprint and compare after creation.','Agreed direction.'],
['I-02','Offered version is equal to or older than the registered version.','Block under version policy. Exceptional reinstall/downgrade needs an explicitly defined procedure.','Explicit user rule; exception details open.'],
['I-03','Offered hash is registered against an older object version.','Block unless the defined explicit exception applies. Use full fingerprint context and version history.','Explicit user rule; ambiguous reuse needs policy.'],
['I-04','Existing fingerprint is unreliable.','Recalculate first; then continue the normal decision tree. A failed calculation is not a valid comparison.','Explicit user rule.'],
['I-05','Offered version is newer; offered fingerprint is new to the module.','Treat as a candidate new object configuration and continue preflight. Difference alone does not interrupt.','Explicit user correction.'],
['I-06','Existing object fingerprint was recalculated and equals the offered fingerprint.','Abort installation and report the finding. Do not convert this branch into automatic approval or silent skip.','Explicit user correction.'],
['I-07','Recalculated existing fingerprint differs from the offered fingerprint.','Treat as a candidate new configuration only when the offered version supports that conclusion. Apply remaining gates.','Explicit user correction.'],
['I-08','Recalculated existing fingerprint differs from its stored accepted fingerprint.','Log and report drift with references to the relevant component inventories. Keep accepted and observed evidence until corrective action.','Explicit user rule; orthogonal to I-06/I-07.'],
['I-09','Fresh trusted stored fingerprint equals offered fingerprint without recalculation.','An earlier assistant proposed skipping the object. The later abort rule explicitly describes recalculation. Confirm whether the no-recalculation branch should skip or abort.','Open; do not silently generalise I-06.'],
['I-10','Post-install actual fingerprint differs from the offered value.','Record/report failed verification. Do not register an accepted successful configuration. Recovery and continuation policy still need definition.','Required comparison agreed; detailed failure policy proposed/open.']])+
p('<strong>Open conflict:</strong> one fingerprint can belong to several successful object versions. For example, versions 1.1 and 1.2 may both have Hash B. “Known older fingerprint” must not be implemented as an unqualified hash-only lookup. The precedence between strict old-configuration rejection and a legitimate newer release with unchanged selected metadata still needs a policy. PM-001 does not invent that exception.')+
p('The earlier rule “any difference between offered and stored fingerprint interrupts installation” is superseded by I-05 and I-07. The earlier “recalculated equals offered: no automatic approval” is sharpened to explicit abort by I-06. An environment drift report under I-08 remains separate from whether the offered release is newer.'),['S07','S08','S09'])

add('PM-001-16','Successful-installation history and evidence','Agreed','History',
p('Keep the fingerprints of every successful installation linked to the installed object versions. A fingerprint identifies selected configuration, not a unique release. Multiple object versions can therefore have the same fingerprint. A fingerprint must not be the sole unique key for history.')+
table(['Object version','Fingerprint','Meaning'],[
['1.0','Hash A','First successful configuration.'],['1.1','Hash B','Selected configuration changed.'],['1.2','Hash B','Version changed; selected configuration did not.'],['1.3','Hash C','Another selected configuration.']])+
p('Hash A/B/C are symbolic. This is not a measured database history. Record the object, version, profile identity/version, canonical format, algorithm, calculation time/result and installation context so that comparisons are interpretable. These are logical information requirements; physical tables and keys still need design.')+
p('Keep three lifecycles distinct: successful-installation fingerprint history; accepted/observed active comparison records; and decision/action audit logs. Replacing active comparison inventories after correction must not be interpreted as deleting all successful-installation history.')+
p('<strong>Open:</strong> history retention, archival, administrator identity, timestamps, links to installation logs, and the treatment of repeated installs of the same version require a physical model. Full old object manifests are not required by this agreement.'),['S08','S10'])

add('PM-001-17','Accepted and observed calculation lifecycle','Agreed','Inventory',
table(['Event','Fingerprint handling','Inventory handling'],[
['Successful verified installation','Register the accepted fingerprint with object version and profile context.','Store inventory from the same successful calculation.'],
['Successful recalculation; equal fingerprint','Keep accepted reference; record calculation result/time as designed.','No extra changed inventory is required.'],
['Successful recalculation; different fingerprint','Retain accepted reference and separate observed result; log/report drift.','Keep original and observed inventories linked to their calculations.'],
['Failed recalculation','Report failure. Do not replace accepted values with incomplete or unknown data.','Do not publish a partial inventory as a successful paired result. This is an implementation safeguard.'],
['Administrator investigates','Keep evidence until corrective action.','Both remain available.'],
['Corrective action complete','Replace active reference as described in the next chapter.','Remove superseded active comparison inventories after recording the decision/action.']])+
p('<code>ACCEPTED</code> and <code>OBSERVED</code> are logical fingerprint roles. They are not automatically the module’s <code>EVALUATION_STATUS</code> values or proposed physical column names. The storage must preserve the distinction without silently overwriting accepted truth.')+
p('<strong>Open:</strong> repeated distinct drift observations before correction, pairing keys, concurrent calculations and retention of failed diagnostic data need explicit implementation rules. The agreement to keep “both” does not decide an unlimited series of intermediate observations.'),['S09','S10'])

add('PM-001-18','Corrective handling after a deviation','Agreed','Correction',
table(['Path','Required sequence','Final active comparison state'],[
['Accept the new reality','The administrator chooses to accept the observed fingerprint and inventory. Record the choice and performed action before replacing the prior accepted values.','The accepted observed pair becomes the new truth. Superseded active comparison data is replaced.'],
['Reinstall / install again','The administrator chooses corrective installation, with an explicit exception if needed. Follow all installation rules. After successful installation and verification, replace the two previous active comparison registrations.','New verified fingerprint and inventory replace both previous comparison registrations.'],
['Correction not complete','Keep the accepted and observed evidence; report the unresolved condition.','No silent promotion or premature deletion.']])+
p('The decision and action record remain available as audit information. The old inventories need not remain as active comparison records after correction. “Delete both registrations” concerns the superseded fingerprint/inventory comparison pair, not deletion of the object’s successful-installation history or the entire object ledger.')+
p('<strong>Open:</strong> how storage changes and audit logging are made recoverable if a step fails. A failed corrective reinstall must not erase the prior comparison evidence. Exact transactions and log retention are implementation work. No fixed number of retention days was agreed.'),['S10'])

add('PM-001-19','Broader ledger, evaluation and lifecycle context','Mixed','History',
p('This chapter preserves the relevant earlier local handoff. Its scope extends beyond PM-001. Later fingerprint-specific decisions take precedence for fingerprint/inventory handling.')+
ul('Keep the existing ledger as the basis for further design. A complete refactoring is not approved.',
'An incomplete installation delivery with missing mandatory lifecycle or removal statements is rejected; log the attempt and reason. An incomplete discovery finding can instead enter PENDING for later review. Those are different routes.',
'One module version is installed at a time. Monitoring-query versions may coexist. Whether physical object versions coexist is open.',
'Module, database, query and log-table versions have separate meanings. CURRENT need not be the highest version.')+
table(['OBJECT_STATUS','Recorded meaning'],[
['ACTIVE','Usable under the conditions, but not the selected version.'],['CURRENT','Selected/in use; not necessarily the highest version.'],['INACTIVE','Explicitly taken out of use, for example due to a bug.'],['FUTURE RELEASE','Needs newer applicable module/database versions.'],['DEPRECATED','Too old for current applicable versions.'],['PENDING','Discovered registration still requires processing and review.'],['ERROR','An error condition, such as missing required objects or Oracle INVALID; report it.']])+
p('<strong>Design direction:</strong> keep <code>OBJECT_STATUS</code> and use <code>EVALUATION_STATUS</code> values ACCEPTED, REJECTED and PENDING. Administrator acceptance does not override ERROR, INACTIVE or unmet applicability conditions. CURRENT + ACCEPTED is the proposed executable combination while its conditions hold.')+
p('Previously reviewed registrations, including CURRENT, are rechecked. A relevant change returns evaluation to PENDING. Already PENDING evaluations are not repeatedly reopened in subsequent inventory rounds. The ledger keeps the latest evaluation/re-evaluation data; further reasons can remain in logs until log cleanup. Full evaluation history was not required.')+
p('<strong>Open:</strong> evaluation transitions, EVALUATED/REEVALUATED field updates, changes that invalidate acceptance, ongoing observation of PENDING items, CURRENT selection and reopening INACTIVE/REJECTED. These are not implemented by this document. The evaluation-history limit does not cancel the later successful-installation fingerprint-history agreement.'),['S12','S08'])

add('PM-001-20','ADMIN_TNSNAMES as design reference','Agreed','Architecture',
p('ADMIN_TNSNAMES is a design and possible code-reuse reference. ADMIN_OBJECTS does not delegate normalisation to that package. A shared utility package is not an agreed requirement.')+
p('The user’s intended split is between candidate registrations processed by <code>ADMIN_TNSNAMES_PROTO</code> and accepted registrations. PROTO performs checks and possible correction, rejects unsuitable input with logging/feedback, and offers technically acceptable input for further administrator approval. This is intended architecture, not proof of the present implementation.')+
p('Useful principles are the separation of definitions, interpretation, concrete values, validation and approval. Reuse of specific code requires source inspection and regression tests. The profile approval workflow can be considered later. It is outside the first normalisation PoC. ADMIN_MONITOR behaviour remains outside this document’s implementation scope.'),['S04','S05','S12'])

add('PM-001-21','PoC scope, stages and efficiency','Mixed','Verification',
p('<strong>Agreed:</strong> build the eventual PoC in Oracle 19c SQL/PLSQL, starting with a manually defined profile and one object manifest. Keep existing production module code untouched. The small experiment must still demonstrate an extensible model with optional/repeated components and stable identities.')+
table(['Stage','Proposed result','Boundary'],[
['1. Contract','Resolve the byte format, exact TABLE_CORE properties and supported object shapes.','Do not assign accepted production meaning to illustrative records.'],
['2. Manual records','Prepare profile/test records and a known reference.','No need for a workflow engine or scheduler.'],
['3. Normalisation / serializer','Demonstrate deterministic typed bytes and controlled failures.','Keep hash-independent byte evidence for diagnosis.'],
['4. Dictionary extraction','Build actual metadata records for a selected test table.','Test under intended privileges and Oracle 19c.'],
['5. Hash and inventory','Calculate complete-input fingerprint and derive the minimal inventory from the same data.','No independent inventory extraction.'],
['6. Integration design','Map results to ledger, pakbon, history and corrective actions.','Production installation integration remains later work.']])+
p('<strong>Open scope conflict:</strong> earlier PoC advice excluded constraints and partitioning; PM-001 later suggested TABLE, COLUMN and limited CONSTRAINT support, then recommended partition-presence plus a repeated category before adding constraints/indexes. These are staged proposals, not one frozen profile. Select the first executable boundary explicitly.')+
p('Measure elapsed time, dictionary calls, rows, canonical byte size and peak memory over representative objects. Compare the stored-fingerprint installation path with the refresh path. No performance gain is measured here. Avoid per-property SQL and repeated extraction; these are efficiency recommendations, not benchmark results.'),['S05','S10','S11'])

tests=[
('T01','Read the same supported metadata twice.','Identical canonical bytes and fingerprint.'),
('T02','Shuffle dictionary input record order.','Identical bytes after the defined ordering.'),
('T03','Change only the readable display or DDL layout.','Identical bytes when selected metadata is unchanged.'),
('T04','Change selected precision, scale or character semantics.','Different bytes; expected different SHA256 digest.'),
('T05','Change selected tablespace.','Different selected bytes and expected different digest.'),
('T06','Add/remove a selected component; test 0, 1 and N repetitions.','Membership is unambiguous; presence changes the bytes.'),
('T07','Omit an optional non-partitioned structure.','Explicit applicable absence in object manifest; no absence inventory line.'),
('T08','Change only a non-selected property.','Identical canonical bytes and fingerprint.'),
('T09','Change profile or canonical version.','Different comparison context; no direct equality conclusion across contexts.'),
('T10','Change NLS settings and include non-ASCII identifiers.','Identical UTF-8 bytes for identical selected values.'),
('T11','Read null, N/A and literal text NULL.','Distinct states where allowed; unknown metadata causes failure.'),
('T12','Supply duplicate identity, unknown normaliser or excessive input.','Explicit failure; no successful partial fingerprint or reference update.'),
('T13','Change only a selected property, preserving identities.','Fingerprint differs; minimal inventory can remain equal.'),
('T14','Recalculate drift, then accept new reality.','Keep both pairs until logged decision/action; then replace active reference.'),
('T15','Reinstall to correct drift; inject verification failure first.','Failure retains comparison evidence; successful verified retry replaces both active pairs.'),
('T16','Exercise I-02 through I-08 with isolated version/history fixtures.','Matrix actions; new hash alone does not block; recalculated equality aborts.'),
('T17','Create target using a DEV/TST claim that does not match.','Report failed verification; no accepted successful registration.'),
('T18','Change metadata during extraction / between preflight and execution.','Detect or prevent mixed/stale observation under the chosen protocol; do not assume consistency.'),
('T19','Install versions 1.1 and 1.2 with the same digest.','Preserve both history links; apply the explicitly chosen reuse policy.'),
('T20','Test ordinary, hidden, virtual, identity, special datatype and partitioned shapes.','Exact supported scope; unsupported shapes are visible, not silently treated as full coverage.')]
add('PM-001-22','Acceptance and verification protocol','Proposal','Verification',
p('These are required future acceptance scenarios, not tests executed for this delivery. Use a dedicated test schema or prepared metadata fixtures. Preserve the exact profile, bytes, expected result, actual result and Oracle version for each run.')+
table(['Test','Scenario','Expected result'],tests)+
p('Different canonical bytes are the deterministic assertion. Different hash output is the expected cryptographic result, not a mathematical no-collision guarantee. Successful document checks do not establish Oracle implementation correctness.'),['S05','S10','S11'])

opens=[
('OP-01','Exact canonical byte protocol','Tags, lengths, framing, encoding, null/N/A and order.','Before reproducible accepted hashes.'),
('OP-02','First TABLE_CORE scope','Constraints, index membership, partition presence, DATA_LENGTH, special columns and datatype limits.','Before executing the PoC.'),
('OP-03','Portable identity','PROFILE_CODE versus surrogate PROFILE_ID; owner/name exclusion; nested identities.','Before cross-environment comparison.'),
('OP-04','Known old hash reused by newer versions','Rule precedence and exceptions when several versions share a digest.','Before production preflight.'),
('OP-05','Trusted equality without recalculation','Skip versus abort; the explicit recalculation branch remains abort.','Before final installation matrix.'),
('OP-06','Freshness and consistency','Validity period, recheck timing, concurrent DDL and refresh failures.','Before production refresh/installation.'),
('OP-07','Pakbon and physical storage','File/table schema, keys, lengths, constraints and links.','Before database implementation.'),
('OP-08','Exceptions and correction failure','Reinstall/downgrade authority, evidence and failure recovery.','Before exception-enabled installation.'),
('OP-09','History and audit retention','Separate installation history from active comparison replacement and log cleanup.','Before retention implementation.'),
('OP-10','Multiple observations and concurrency','Several drift results, pairing, locking and atomic publication.','Before scheduled integration.'),
('OP-11','Broader evaluation transitions','CURRENT selection, veto, re-evaluation fields and pending observations.','Separate module design work.'),
('OP-12','Hash implementation','Bounded input versus LOB-safe path; privileges and byte conversion.','Before Oracle validation.')]
add('PM-001-23','Open-decision register','Open','Decisions',
table(['ID','Decision','Scope','Decision needed'],opens)+
p('Closed by the latest user decision: inventory detail is minimal; deviation cleanup follows a corrective action; acceptance of new reality or verified reinstall replaces active comparison data after logging the decision/action. These points must not reappear as unresolved design choices.'),['S08','S09','S10','S12'])

add('PM-001-24','Superseded proposals and precedence','Mixed','Decisions',
table(['Earlier text','Current treatment','Reason'],[
['Permanent full object-manifest history by default','Not adopted. Profile permanent; object manifest ad hoc; minimal inventory retained under lifecycle rules.','User clarification and final PM-001.'],
['Inventory includes datatype and precision','Superseded by type + identity only.','Explicit minimal-inventory acceptance.'],
['Inventory contains PARTITIONED=NO','Excluded from inventory; relevant absence remains canonical metadata.','Explicit distinction.'],
['Any offered hash difference interrupts installation','Superseded: newer version + new hash is a candidate.','Explicit installation correction.'],
['Recalculated equals offered can be approved','Explicit branch aborts and reports.','User sharpened the action.'],
['Production reconstructs expected hash from offered DDL','Not required. DEV/TST supply it; verify actual target after creation.','User clarified origin.'],
['INSTALLATION_ORDER and object relationship administration','Not a settled pakbon requirement; removal proposed after user rejected relationship management.','Responsibility boundary.'],
['Retain both comparison inventories without a resolution policy','Replaced by corrective-action acceptance or verified reinstall.','Final user decision.'],
['SHA256 choice means a final serializer exists','Incorrect. SHA256 is the profile proposal; exact canonical bytes remain open.','PM-001 explicitly leaves byte encoding open.']])+
p('Documentation approval authorises consolidation, not automatic approval of each assistant-proposed field, status or physical design. Later explicit user corrections override earlier assistant examples. Oracle technical limitations remain separate from policy choices.'),['S01','S07','S08','S09','S10'])

